class Solution:
    def minOrAfterOperations(self, nums: List[int], k: int) -> int:
        n = len(nums)
        need = n - k
        FULL = (1 << 30) - 1

        def feasible(forbidden):
            count = 0
            cur = FULL
            for x in nums:
                cur &= x
                if cur & forbidden == 0:
                    count += 1
                    cur = FULL
            return count >= need and count >= 1

        forbidden = 0
        for bit in range(29, -1, -1):
            cand = forbidden | (1 << bit)
            if feasible(cand):
                forbidden = cand
        return (~forbidden) & FULL
